{{ config(materialized = 'ephemeral') }}

-- SALESFORCECOMPANY -> company_core: generated by dbt-onboard-source from the approved STTM.
-- SOURCE_UNIQUE_ID: STTM business keys.

with sp_company_core as (
    select
        upper(trim(o.ID)) as source_unique_id,
        nullif(trim(o.DUNSNUMBER), '') as duns_number,
        nullif(trim(o.COMPANY_NAME), '') as company_name,
        nullif(trim(o.WEBSITE), '') as website_url,
        o._LOAD_TS
    from {{ source('company_core_salesforcecompany_source', 'account') }} as o
    where nullif(upper(trim(o.ID)), '') is not null
    qualify row_number() over (partition by upper(trim(o.ID)) order by o._LOAD_TS desc) = 1
),

ref_source_system as (
    {{ m_get_source_system_skey_company('SALESFORCECOMPANY') }}
),

base as (
    select
        o.source_unique_id,
        r.gdp_source_system_skey as ref_gdp_source_system_skey,
        o.duns_number as duns_number,
        o.company_name as company_name,
        null as alias_name,
        null as ref_company_type_skey /* TODO: FK lookup pending: add ref CTE + LEFT JOIN on upper(trim(...)) for REF_COMPANY_TYPE_SKEY */,
        null as ref_country_of_registration_skey /* TODO: FK lookup pending: add ref CTE + LEFT JOIN on upper(trim(...)) for REF_COUNTRY_OF_REGISTRATION_SKEY */,
        null as ref_address_skey /* TODO: FK lookup pending: add ref CTE + LEFT JOIN on upper(trim(...)) for REF_ADDRESS_SKEY */,
        o.website_url as website_url,
        null as is_cbre_entity,
        null as company_status,
        true as gdp_is_active,
        current_timestamp()::timestamp_ntz as gdp_inserted_ts,
        current_user() as gdp_inserted_by,
        o._LOAD_TS as gdp_updated_ts,
        current_user() as gdp_updated_by
    from sp_company_core as o
    cross join ref_source_system as r
)

select
    {{ this.schema }}.seq_company_core_skey.nextval as company_core_skey,
    source_unique_id,
    ref_gdp_source_system_skey,
    duns_number,
    company_name,
    alias_name,
    ref_company_type_skey,
    ref_country_of_registration_skey,
    ref_address_skey,
    website_url,
    is_cbre_entity,
    company_status,
    {{ m_company_core_hkey() }} as company_core_hkey,
    gdp_is_active,
    gdp_inserted_ts,
    gdp_inserted_by,
    gdp_updated_ts,
    gdp_updated_by
from base
